css:
.board {
  display: flex;
  align-items: flex-start; /* columns keep their own height */
  gap: 12px;
  padding: 12px;
  overflow-x: auto;
}

.column {
  flex: 0 0 200px;
  min-width: 0;
  height: 280px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 12px;
  overflow-y: auto; /* scrolls on its own */
  background: #f4f4f5;
  border-radius: 8px;
}

.col-title {
  margin: 0;
  font-weight: 600;
}

.task {
  flex-shrink: 0;
  padding: 10px;
  background: #fff;
  border: 1px solid #d4d4d8;
  border-radius: 6px;
}
